{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01PkSt9d6xCGHMwxCmp1xoeU","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01YKxLRVm9mHiuvoaWzVNvEw","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"gpu-6000pro-2","command":"cat > /root/autodl-tmp/recursive_gen_depth_est/scripts/dcol_trainer_v4.py << 'PYEOF'\n\"\"\"\nDCOL v4: DeBERTa-v3-large + LoRA + Contrastive Ordinal Loss\nChanges from v3:\n  - LoRA fine-tuning instead of full fine-tuning (preserves pretrained representations)\n  - Separate margin_lr (<=1e-4) to prevent embedding collapse\n  - Mid-epoch eval every N global steps + early stopping\n\"\"\"\n\nimport argparse\nimport glob\nimport json\nimport math\nimport os\nimport random\nimport re\nimport time\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom torch.amp import autocast\nfrom torch.cuda.amp import GradScaler\nfrom torch.utils.data import DataLoader, Dataset, random_split\nfrom transformers import AutoModel, AutoTokenizer\nfrom peft import get_peft_model, LoraConfig, TaskType\n\n\ndef set_seed(seed: int):\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    torch.cuda.manual_seed_all(seed)\n\n\nclass DepthDataset(Dataset):\n    def __init__(self, texts, labels, tokenizer, max_seq_len):\n        self.texts = texts\n        self.labels = labels\n        self.tokenizer = tokenizer\n        self.max_seq_len = max_seq_len\n\n    def __len__(self):\n        return len(self.texts)\n\n    def __getitem__(self, idx):\n        enc = self.tokenizer(\n            self.texts[idx],\n            max_length=self.max_seq_len,\n            padding=\"max_length\",\n            truncation=True,\n            return_tensors=\"pt\",\n        )\n        return {\n            \"input_ids\": enc[\"input_ids\"].squeeze(0),\n            \"attention_mask\": enc[\"attention_mask\"].squeeze(0),\n            \"label\": self.labels[idx],\n        }\n\n\nclass DCOLModelV4(nn.Module):\n    \"\"\"LoRA-wrapped DeBERTa + classifier + learnable ordinal margins.\"\"\"\n\n    def __init__(self, model_name, num_depths=4, margin_init=1.0,\n                 lora_r=16, lora_alpha=32, lora_dropout=0.1):\n        super().__init__()\n        base_encoder = AutoModel.from_pretrained(model_name)\n        hidden_size = base_encoder.config.hidden_size\n\n        lora_config = LoraConfig(\n            task_type=TaskType.FEATURE_EXTRACTION,\n            r=lora_r,\n            lora_alpha=lora_alpha,\n            lora_dropout=lora_dropout,\n            target_modules=[\"query_proj\", \"value_proj\"],\n        )\n        self.encoder = get_peft_model(base_encoder, lora_config)\n        self.classifier = nn.Linear(hidden_size, num_depths)\n        self.log_margins = nn.Parameter(\n            torch.full((num_depths - 1,), math.log(margin_init))\n        )\n\n    @property\n    def margins(self):\n        raw = self.log_margins.exp()\n        return torch.cumsum(raw, dim=0)\n\n    def forward(self, input_ids, attention_mask):\n        outputs = self.encoder(input_ids=input_ids, attention_mask=attention_mask)\n        token_embs = outputs.last_hidden_state\n        mask = attention_mask.unsqueeze(-1).float()\n        pooled = (token_embs * mask).sum(dim=1) / mask.sum(dim=1).clamp(min=1e-9)\n        logits = self.classifier(pooled)\n        return pooled, logits\n\n    def print_trainable_params(self):\n        total = sum(p.numel() for p in self.parameters())\n        trainable = sum(p.numel() for p in self.parameters() if p.requires_grad)\n        lora_params = sum(p.numel() for n, p in self.encoder.named_parameters() if p.requires_grad)\n        cls_params = sum(p.numel() for p in self.classifier.parameters())\n        margin_params = self.log_margins.numel()\n        print(f\"Total params:     {total:>12,}\")\n        print(f\"Trainable params: {trainable:>12,} ({100*trainable/total:.2f}%)\")\n        print(f\"  LoRA:           {lora_params:>12,}\")\n        print(f\"  Classifier:     {cls_params:>12,}\")\n        print(f\"  Margins:        {margin_params:>12,}\")\n        return total, trainable\n\n\ndef contrastive_ordinal_loss(embeddings, labels, margins):\n    alpha = 0.1\n    B = embeddings.size(0)\n    if B < 2:\n        return embeddings.new_tensor(0.0)\n\n    diff = embeddings.unsqueeze(0) - embeddings.unsqueeze(1)\n    dists = (diff.pow(2).sum(dim=-1) + 1e-8).sqrt()\n    label_dists = (labels.unsqueeze(0) - labels.unsqueeze(1)).abs()\n\n    same_mask = (label_dists == 0).float()\n    same_mask.fill_diagonal_(0)\n    diff_mask = (label_dists > 0).float()\n\n    attractive = F.relu(dists - alpha) * same_mask\n    margin_matrix = margins[(label_dists.clamp(min=1) - 1).long()]\n    repulsive = F.relu(margin_matrix - dists + alpha) * diff_mask\n\n    n_same = same_mask.sum().clamp(min=1)\n    n_diff = diff_mask.sum().clamp(min=1)\n    return attractive.sum() / n_same + repulsive.sum() / n_diff\n\n\ndef load_data(data_dirs):\n    texts, labels = [], []\n    depth_pattern = re.compile(r\"^depth_(\\d+)\\.jsonl$\")\n    for d in data_dirs:\n        files = sorted(glob.glob(os.path.join(d, \"depth_*.jsonl\")))\n        if not files:\n            print(f\"WARNING: no depth_*.jsonl in {d}\")\n            continue\n        for f in files:\n            fname = os.path.basename(f)\n            m = depth_pattern.match(fname)\n            if not m:\n                continue\n            depth = int(m.group(1))\n            with open(f) as fh:\n                for line in fh:\n                    line = line.strip()\n                    if not line:\n                        continue\n                    item = json.loads(line)\n                    texts.append(item[\"text\"])\n                    labels.append(depth)\n        print(f\"  Loaded from {d}: {len(files)} files\")\n    print(f\"Total samples: {len(texts)}\")\n    return texts, labels\n\n\ndef evaluate(model, dataloader, device, use_amp):\n    model.eval()\n    correct, total = 0, 0\n    total_loss_ce = 0.0\n    mae_sum = 0.0\n    num_classes = 4\n    class_correct = [0] * num_classes\n    class_total = [0] * num_classes\n    amp_device = \"cuda\" if device.type == \"cuda\" else \"cpu\"\n\n    with torch.no_grad():\n        for batch in dataloader:\n            input_ids = batch[\"input_ids\"].to(device)\n            attention_mask = batch[\"attention_mask\"].to(device)\n            blabels = batch[\"label\"].to(device)\n\n            with autocast(amp_device, enabled=use_amp):\n                _, logits = model(input_ids, attention_mask)\n                loss_ce = F.cross_entropy(logits, blabels)\n\n            total_loss_ce += loss_ce.item() * blabels.size(0)\n            preds = logits.argmax(dim=-1)\n            correct += (preds == blabels).sum().item()\n            total += blabels.size(0)\n            mae_sum += (preds - blabels).abs().float().sum().item()\n\n            for c in range(num_classes):\n                mask_c = blabels == c\n                class_total[c] += mask_c.sum().item()\n                class_correct[c] += ((preds == blabels) & mask_c).sum().item()\n\n    acc = correct / max(total, 1)\n    avg_ce = total_loss_ce / max(total, 1)\n    per_class_acc = [class_correct[c] / max(class_total[c], 1) for c in range(num_classes)]\n    mae = mae_sum / max(total, 1)\n    return acc, avg_ce, per_class_acc, mae\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"DCOL v4: LoRA + Contrastive Ordinal Loss\")\n    parser.add_argument(\"--data_dirs\", nargs=\"+\", required=True)\n    parser.add_argument(\"--model_name\", type=str, default=\"/root/autodl-tmp/models/deberta-v3-large\")\n    parser.add_argument(\"--output_dir\", type=str, default=\"checkpoints/dcol_v4/\")\n    parser.add_argument(\"--max_seq_len\", type=int, default=512)\n    parser.add_argument(\"--batch_size\", type=int, default=8)\n    parser.add_argument(\"--gradient_accumulation\", type=int, default=4)\n    parser.add_argument(\"--epochs\", type=int, default=10)\n    parser.add_argument(\"--max_steps\", type=int, default=-1, help=\"Stop after N global steps (-1=unlimited)\")\n    parser.add_argument(\"--lr\", type=float, default=2e-5)\n    parser.add_argument(\"--margin_lr\", type=float, default=1e-4, help=\"Must be <=1e-4\")\n    parser.add_argument(\"--warmup_ratio\", type=float, default=0.1)\n    parser.add_argument(\"--lambda_contrastive\", type=float, default=1.0)\n    parser.add_argument(\"--lambda_ce\", type=float, default=0.5)\n    parser.add_argument(\"--margin_init\", type=float, default=1.0)\n    parser.add_argument(\"--num_depths\", type=int, default=4)\n    parser.add_argument(\"--lora_r\", type=int, default=16)\n    parser.add_argument(\"--lora_alpha\", type=int, default=32)\n    parser.add_argument(\"--lora_dropout\", type=float, default=0.1)\n    parser.add_argument(\"--seed\", type=int, default=42)\n    parser.add_argument(\"--bf16\", action=\"store_true\", default=True)\n    parser.add_argument(\"--no_bf16\", dest=\"bf16\", action=\"store_false\")\n    parser.add_argument(\"--gpu\", type=int, default=0)\n    parser.add_argument(\"--eval_split\", type=float, default=0.1)\n    parser.add_argument(\"--eval_steps\", type=int, default=100, help=\"Eval every N global steps\")\n    parser.add_argument(\"--log_every\", type=int, default=20, help=\"Log every N global steps\")\n    parser.add_argument(\"--patience\", type=int, default=5, help=\"Early stopping patience (eval rounds)\")\n    parser.add_argument(\"--dry_run\", action=\"store_true\")\n    parser.add_argument(\"--use_wandb\", action=\"store_true\")\n    parser.add_argument(\"--wandb_name\", type=str, default=\"dcol_v4_lora\")\n    args = parser.parse_args()\n\n    assert args.margin_lr <= 1e-4, f\"margin_lr={args.margin_lr} exceeds 1e-4 limit!\"\n\n    if args.dry_run and args.max_steps < 0:\n        args.max_steps = 3\n\n    set_seed(args.seed)\n\n    device = torch.device(f\"cuda:{args.gpu}\" if torch.cuda.is_available() else \"cpu\")\n    if device.type == \"cuda\":\n        print(f\"GPU: {torch.cuda.get_device_name(device)}\")\n\n    use_amp = args.bf16 and device.type == \"cuda\"\n    amp_dtype = torch.bfloat16\n    amp_device = \"cuda\" if device.type == \"cuda\" else \"cpu\"\n\n    # Data\n    print(\"Loading data...\")\n    texts, labels = load_data(args.data_dirs)\n    assert len(texts) > 0, \"No data loaded\"\n\n    tokenizer = AutoTokenizer.from_pretrained(args.model_name)\n    dataset = DepthDataset(texts, labels, tokenizer, args.max_seq_len)\n    val_size = int(len(dataset) * args.eval_split)\n    train_size = len(dataset) - val_size\n    train_dataset, val_dataset = random_split(\n        dataset, [train_size, val_size],\n        generator=torch.Generator().manual_seed(args.seed),\n    )\n    print(f\"Train: {train_size}, Val: {val_size}\")\n\n    train_loader = DataLoader(\n        train_dataset, batch_size=args.batch_size, shuffle=True,\n        num_workers=2, pin_memory=(device.type == \"cuda\"),\n    )\n    val_loader = DataLoader(\n        val_dataset, batch_size=args.batch_size * 2, shuffle=False,\n        num_workers=2, pin_memory=(device.type == \"cuda\"),\n    )\n\n    # Model\n    print(f\"Loading model: {args.model_name} (LoRA r={args.lora_r} alpha={args.lora_alpha})\")\n    model = DCOLModelV4(\n        args.model_name, args.num_depths, args.margin_init,\n        lora_r=args.lora_r, lora_alpha=args.lora_alpha, lora_dropout=args.lora_dropout,\n    ).to(device)\n    total_params, trainable_params = model.print_trainable_params()\n    print(f\"Initial margins: {model.margins.detach().cpu().tolist()}\")\n\n    # Optimizer: separate groups for LoRA, classifier, and margins\n    lora_params = [p for n, p in model.encoder.named_parameters() if p.requires_grad]\n    optimizer = torch.optim.AdamW([\n        {\"params\": lora_params, \"lr\": args.lr, \"weight_decay\": 0.01},\n        {\"params\": list(model.classifier.parameters()), \"lr\": args.lr, \"weight_decay\": 0.01},\n        {\"params\": [model.log_margins], \"lr\": args.margin_lr, \"weight_decay\": 0.0},\n    ])\n\n    steps_per_epoch = len(train_loader) // args.gradient_accumulation\n    total_steps = steps_per_epoch * args.epochs\n    if args.max_steps > 0:\n        total_steps = min(total_steps, args.max_steps)\n    warmup_steps = int(total_steps * args.warmup_ratio)\n\n    def lr_lambda(current_step):\n        if current_step < warmup_steps:\n            return current_step / max(warmup_steps, 1)\n        progress = (current_step - warmup_steps) / max(total_steps - warmup_steps, 1)\n        return max(0.0, 0.5 * (1.0 + math.cos(math.pi * progress)))\n\n    scheduler = torch.optim.lr_scheduler.LambdaLR(optimizer, lr_lambda)\n    scaler = GradScaler(enabled=use_amp)\n\n    if args.use_wandb:\n        import wandb\n        wandb.init(project=\"recursive_gen_depth_est\", name=args.wandb_name, config=vars(args))\n\n    os.makedirs(args.output_dir, exist_ok=True)\n\n    print(f\"\\n{'='*60}\")\n    print(f\"DCOL v4 — LoRA fine-tuning\")\n    print(f\"Epochs: {args.epochs}, Total steps: ~{total_steps}, Eval every: {args.eval_steps} steps\")\n    print(f\"Effective batch: {args.batch_size * args.gradient_accumulation}\")\n    print(f\"LR: {args.lr}, Margin LR: {args.margin_lr}, Warmup: {warmup_steps} steps\")\n    print(f\"{'='*60}\\n\")\n\n    best_val_acc = 0.0\n    global_step = 0\n    patience_counter = 0\n    stop_training = False\n\n    def run_eval(tag=\"\"):\n        nonlocal best_val_acc, patience_counter, stop_training\n        val_acc, val_ce, per_class_acc, val_mae = evaluate(model, val_loader, device, use_amp)\n        margins_v = model.margins.detach().cpu().tolist()\n        print(\n            f\"  [{tag} GS={global_step}] val_acc={val_acc:.4f} val_ce={val_ce:.4f} \"\n            f\"val_mae={val_mae:.4f} margins={[f'{m:.3f}' for m in margins_v]}\"\n        )\n        print(f\"    per_class: \" + \" \".join(f\"d{i}={a:.4f}\" for i, a in enumerate(per_class_acc)))\n\n        if args.use_wandb:\n            import wandb\n            log_dict = {\"val/acc\": val_acc, \"val/ce\": val_ce, \"val/mae\": val_mae, \"global_step\": global_step}\n            for i, a in enumerate(per_class_acc):\n                log_dict[f\"val/acc_d{i}\"] = a\n            for i, m in enumerate(margins_v):\n                log_dict[f\"margin/{i+1}\"] = m\n            wandb.log(log_dict)\n\n        if val_acc > best_val_acc:\n            best_val_acc = val_acc\n            patience_counter = 0\n            ckpt_path = os.path.join(args.output_dir, \"best_model.pt\")\n            torch.save({\n                \"global_step\": global_step,\n                \"encoder_state_dict\": model.encoder.state_dict(),\n                \"classifier_state_dict\": model.classifier.state_dict(),\n                \"log_margins\": model.log_margins.data,\n                \"val_acc\": val_acc, \"val_mae\": val_mae,\n                \"margins\": margins_v, \"args\": vars(args),\n            }, ckpt_path)\n            print(f\"    -> New best val_acc={val_acc:.4f}, saved to {ckpt_path}\")\n        else:\n            patience_counter += 1\n            print(f\"    No improvement ({patience_counter}/{args.patience})\")\n            if patience_counter >= args.patience:\n                print(f\"    Early stopping triggered\")\n                stop_training = True\n\n        model.train()\n        return val_acc\n\n    for epoch in range(args.epochs):\n        if stop_training:\n            break\n        model.train()\n        epoch_loss = 0.0\n        epoch_correct = 0\n        epoch_total = 0\n        optimizer.zero_grad()\n        t0 = time.time()\n\n        for step, batch in enumerate(train_loader):\n            input_ids = batch[\"input_ids\"].to(device)\n            attention_mask = batch[\"attention_mask\"].to(device)\n            batch_labels = batch[\"label\"].to(device)\n\n            with autocast(amp_device, enabled=use_amp, dtype=amp_dtype if use_amp else torch.float32):\n                embeddings, logits = model(input_ids, attention_mask)\n                loss_ce = F.cross_entropy(logits, batch_labels)\n                loss_con = contrastive_ordinal_loss(embeddings, batch_labels, model.margins)\n                loss = args.lambda_ce * loss_ce + args.lambda_contrastive * loss_con\n                loss = loss / args.gradient_accumulation\n\n            scaler.scale(loss).backward()\n\n            if (step + 1) % args.gradient_accumulation == 0:\n                scaler.unscale_(optimizer)\n                torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n                scaler.step(optimizer)\n                scaler.update()\n                scheduler.step()\n                optimizer.zero_grad()\n                global_step += 1\n\n                # Logging\n                if global_step % args.log_every == 0:\n                    avg_loss = epoch_loss / max(step + 1, 1)\n                    acc = epoch_correct / max(epoch_total, 1)\n                    margins_now = model.margins.detach().cpu().tolist()\n                    lr_now = scheduler.get_last_lr()[0]\n                    mlr_now = scheduler.get_last_lr()[2]\n                    print(\n                        f\"  [E{epoch+1} GS={global_step}] loss={avg_loss:.4f} acc={acc:.4f} \"\n                        f\"margins={[f'{m:.3f}' for m in margins_now]} lr={lr_now:.2e} mlr={mlr_now:.2e}\"\n                    )\n                    if args.use_wandb:\n                        import wandb\n                        wandb.log({\n                            \"train/loss\": avg_loss, \"train/acc\": acc, \"train/lr\": lr_now,\n                            \"train/margin_lr\": mlr_now,\n                            \"train/margin_1\": margins_now[0], \"train/margin_2\": margins_now[1],\n                            \"train/margin_3\": margins_now[2], \"global_step\": global_step,\n                        })\n\n                # Mid-epoch 